function c23720856.cfilter(c)
	return c:IsFaceup() and c:IsSetCard(0x8f,0x54) and not c:IsCode(23720856)
end

function c23720856.cfilter(c)
	return c:IsFaceup() and c:IsSetCard(0x8f,0x54) and not c:IsCode(23720856)
